import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSingleFlight } from '../../query/useSingleFlight';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useGrades } from '../people/usePeople';
import { useSheetToday } from '../today/useSheetToday';
import { useDueTotals, useExcess, useSettledOpenTotals } from './useDueTotals';
import { useRatePreview } from './useRatePreview';
import { rateFor, ratesKey, trimmedSum, useRates, type Rate } from './useRates';
import { useFigure } from '../locale/useLocale';
import { Col } from '../columns/useColumns';

/** The sheet's rates for each grade: a form that sets one from an optional from-date (a new version of the
 *  grade's rate from that date, the one in force; blank is from the beginning of time) through an optional to-date
 *  (blank is no end), the rates set, and the rate in
 *  force on the sheet's today for every grade ('n/a' when none is). */
function Rates({ sheetId }: { sheetId: string }) {
  const grades = useGrades(sheetId);
  const fig = useFigure();
  const rates = useRates(sheetId);
  const today = useSheetToday(sheetId);
  const queryClient = useQueryClient();
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const submitOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { grade: string; pct: string; from: string; to: string }) =>
      postJson<Rate>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`, f),
    onSuccess: async () => {
      setPct('');
      setFrom('');
      setTo('');
      await queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
    },
  });

  return (
    <section data-testid="rates">
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ grade, pct, from, to });
          });
        }}
      >
        <label>
          Grade{' '}
          <select
            data-testid="rate-form-grade"
            value={grade}
            onChange={(e) => {
              setGrade(e.target.value);
              save.reset();
            }}
          >
            {grades.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          Rate %{' '}
          <input
            data-testid="rate-form-pct"
            inputMode="decimal"
            value={pct}
            onChange={(e) => {
              setPct(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="text"
            placeholder="yyyy-mm-dd"
            data-testid="rate-form-from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            type="text"
            placeholder="yyyy-mm-dd"
            data-testid="rate-form-to"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="rate-form-submit" disabled={save.isPending}>
          Set rate
        </button>
        {save.isError && <p data-testid="rate-form-error">{save.error.message}</p>}
      </form>
      <table data-testid="rates-list">
        <thead>
          <tr>
            <th>Grade</th>
            <th>Rate %</th>
            <th>From</th>
            <th>To</th>
            <th>Versions</th>
          </tr>
        </thead>
        <tbody>
          {(rates.data ?? []).filter((r) => r.level === 0 && !r.superseded).map((r) => (
            <tr key={`${r.grade}-${r.from ?? 'start'}`} data-testid={`rate-row-${r.grade}-${r.from ?? 'start'}`}>
              <td data-testid="rate-grade">{r.grade}</td>
              <td data-testid="rate-pct">{fig(r.pct)}</td>
              <td data-testid="rate-from">{r.from ?? ''}</td>
              <td data-testid="rate-to">{r.to ?? ''}</td>
              <td data-testid="rate-version">{r.version ?? 1}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <p>
        Current rates:{' '}
        {grades.map((g) => (
          <span key={g}>
            {g} <strong data-testid={`rate-current-${g}`}>{fig(rateFor(rates.data, g, today.data?.today) ?? 'n/a')}</strong>{' '}
          </span>
        ))}
      </p>
      <RateCalendar sheetId={sheetId} />
      <ImportRates sheetId={sheetId} />
      <RatePreview sheetId={sheetId} />
      {rates.isError && <p data-testid="rates-error">{rates.error.message}</p>}
    </section>
  );
}

/** The rate calendar: for every grade and each month of the sheet's today's calendar year, the rate in force
 *  on the first day of that month ('n/a' when none is). */
function RateCalendar({ sheetId }: { sheetId: string }) {
  const grades = useGrades(sheetId);
  const fig = useFigure();
  const rates = useRates(sheetId);
  const year = useSheetToday(sheetId).data?.today?.slice(0, 4);
  if (year === undefined) return null;
  const months = Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`);
  return (
    <table data-testid="rate-calendar">
      <thead>
        <tr>
          <th>Grade</th>
          {months.map((m) => (
            <th key={m}>{m}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {grades.map((g) => (
          <tr key={g}>
            <td>{g}</td>
            {months.map((m) => (
              <td key={m} data-testid={`rate-month-${g}-${m}`}>{fig(rateFor(rates.data, g, `${m}-01`) ?? 'n/a')}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/** A rate import box: lines of grade,rate,from,to (the from and to may be absent or blank), each set in
 *  order as the rate form sets it. The server checks every line first: one refused line refuses the import
 *  and sets nothing. Shows how many were set (gone while it runs). */
function ImportRates({ sheetId }: { sheetId: string }) {
  const [text, setText] = useState('');
  const queryClient = useQueryClient();
  const submitOnce = useSingleFlight();
  const importRates = useMutation({
    mutationFn: (t: string) =>
      postJson<{ set: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/rate-import`, { text: t }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: ratesKey(sheetId) });
    },
  });
  return (
    <form
      data-testid="import-rates-form"
      onSubmit={(e) => {
        e.preventDefault();
        submitOnce(() => {
          importRates.reset();
          return importRates.mutateAsync(text);
        });
      }}
    >
      <label>
        Import rates (grade,rate,from,to per line){' '}
        <textarea
          data-testid="import-rates"
          rows={3}
          value={text}
          onChange={(e) => {
            setText(e.target.value);
            importRates.reset();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="import-rates-submit" disabled={importRates.isPending}>
        Import rates
      </button>
      {importRates.isSuccess && (
        <>
          {' '}
          Set <strong data-testid="import-rates-set">{importRates.data.set}</strong>
        </>
      )}
      {importRates.isError && <p data-testid="import-rates-error">{importRates.error.message}</p>}
    </form>
  );
}

/** A preview of a candidate rate for a grade (see `useRatePreview`): how many claims would show a different
 *  due and the sum of the differences. Nothing is saved. The result is cleared when the form changes. */
function RatePreview({ sheetId }: { sheetId: string }) {
  const grades = useGrades(sheetId);
  const fig = useFigure();
  const preview = useRatePreview(sheetId);
  const [grade, setGrade] = useState<string>('A');
  const [pct, setPct] = useState('');
  const [result, setResult] = useState<{ count: number; diff: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const clear = () => {
    setResult(null);
    setError(null);
  };

  return (
    <form
      data-testid="rate-preview-form"
      onSubmit={(e) => {
        e.preventDefault();
        clear();
        try {
          const r = preview(grade, pct);
          setTimeout(() => setResult(r), 0);
        } catch (err) {
          setError((err as Error).message);
        }
      }}
    >
      <label>
        Preview grade{' '}
        <select
          data-testid="rate-preview-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            clear();
          }}
        >
          {grades.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </label>{' '}
      <label>
        Rate %{' '}
        <input
          data-testid="rate-preview-pct"
          inputMode="decimal"
          value={pct}
          onChange={(e) => {
            setPct(e.target.value);
            clear();
          }}
        />
      </label>{' '}
      <button type="submit" data-testid="rate-preview">
        Preview
      </button>
      {result !== null && (
        <span>
          {' '}
          Would change <strong data-testid="rate-preview-count">{result.count}</strong> claims by{' '}
          <strong data-testid="rate-preview-diff">{fig(result.diff)}</strong>
        </span>
      )}
      {error !== null && <p data-testid="rate-preview-error">{error}</p>}
    </form>
  );
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const fig = useFigure();
  const totals = useDueTotals(sheetId);
  return <Col id="due-total"><td data-testid="person-due-total">{fig(totals.get(personId) ?? '')}</td></Col>;
}

/** A person's excess: how far the sum of their figures is above the sheet's cap. */
function PersonExcess({ sheetId, personId }: { sheetId: string; personId: number }) {
  const fig = useFigure();
  const excess = useExcess(sheetId);
  return <Col id="excess"><td data-testid="person-excess">{fig(excess.get(personId) ?? '')}</td></Col>;
}

/** A person's settled-total and open-total: the parts of their due-total (before the cap) from their
 *  SETTLED claims and from their open (OPEN or PENDING) claims. */
function PersonSettledOpen({ sheetId, personId }: { sheetId: string; personId: number }) {
  const fig = useFigure();
  const split = useSettledOpenTotals(sheetId).get(personId);
  return (
    <>
      <td data-testid="person-settled-total">{fig(split?.settled ?? '')}</td>
      <td data-testid="person-open-total">{fig(split?.open ?? '')}</td>
    </>
  );
}

/** The sheet's settled-total and open-total: everyone's figure added up, leaving out the highest and the
 *  lowest when three or more people have one. */
function SettledOpenTotals({ sheetId }: { sheetId: string }) {
  const fig = useFigure();
  const split = [...useSettledOpenTotals(sheetId).values()];
  return (
    <p>
      Settled total: <strong data-testid="rollup-settled-total">{fig(trimmedSum(split.map((s) => s.settled)))}</strong>,
      open total <strong data-testid="rollup-open-total">{fig(trimmedSum(split.map((s) => s.open)))}</strong>
    </p>
  );
}

/** The sheet's due-total: everyone's due-total added up, skipping 'n/a',
 *  leaving out the highest and the lowest when three or more people have one. */
function DueTotal({ sheetId }: { sheetId: string }) {
  const fig = useFigure();
  const totals = useDueTotals(sheetId);
  return (
    <p>
      Due total: <strong data-testid="rollup-due-total">{fig(trimmedSum([...totals.values()]))}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 5, Component: ({ sheetId }) => <Rates sheetId={sheetId} /> }),
  PersonColumnHead.fill({ order: 20, Component: () => <Col id="due-total"><th>Due</th></Col> }),
  PersonCells.fill({ order: 20, Component: PersonDueTotal }),
  PersonColumnHead.fill({ order: 21, Component: () => <Col id="excess"><th>Excess</th></Col> }),
  PersonCells.fill({ order: 21, Component: PersonExcess }),
  PersonColumnHead.fill({ order: 21.5, Component: () => <><th>Settled</th><th>Open</th></> }),
  PersonCells.fill({ order: 21.5, Component: PersonSettledOpen }),
  SheetBody.fill({ order: 30, Component: ({ sheetId }) => <DueTotal sheetId={sheetId} /> }),
  SheetBody.fill({ order: 31, Component: ({ sheetId }) => <SettledOpenTotals sheetId={sheetId} /> }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useReader } from '../../api/readNow';

/** A grade's rate: a percent with two decimals, in force from its from-date (yyyy-mm-dd; null when it
 *  applies from the beginning of time) through its to-date (null when it has no end), and its `version`: how many versions the grade's rate from that
 *  from-date has had (this is the newest, the one in force). `level` is the sheet it
 *  is set on: 0 this sheet, 1 its parent, 2 the parent's parent, 3 the one above that. `after`: for a forward-only
 *  rate (saved with a from-date on or after the sheet's today), the claim-added number it was saved at — it applies
 *  only to claims added after it (see `Claim.added`); null when it applies to every claim. `superseded`: an older
 *  version, kept only for the claims a newer forward-only version does not apply to (never shown, never in force). */
export type Rate = {
  grade: string; pct: string; from: string | null; to: string | null; version?: number; level?: number;
  after?: number | null; superseded?: boolean;
};

export function ratesKey(sheetId: string) {
  return ['sheet', sheetId, 'rates'];
}

/** The sheet's rates (level 0), by grade then from-date (an undated rate first); a grade with no rate is not
 *  listed. Then those of the sheets its grades fall back to, nearest first (level 1 its parent, up to 3). Then the
 *  older (superseded) versions of all of them, for the claims they still apply to. */
export function useRates(sheetId: string) {
  const read = useReader();
  return useQuery({
    queryKey: read.key(ratesKey(sheetId)),
    queryFn: async () => {
      const got = await read.get<{ rates: Rate[]; inherited: Rate[][]; earlier: Rate[]; inheritedEarlier: Rate[][] }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/rates`);
      return [
        ...got.rates.map((r) => ({ ...r, level: 0 })),
        ...(got.inherited ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1 }))),
        ...(got.earlier ?? []).map((r) => ({ ...r, level: 0, superseded: true })),
        ...(got.inheritedEarlier ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1, superseded: true }))),
      ];
    },
  });
}

/** The rate (a two-decimal percent) for a grade in force on a date (yyyy-mm-dd): on this sheet, the one with
 *  the latest from-date on or before it, an undated rate applying from the beginning of time, unless the date is
 *  after that rate's to-date; when this sheet has none in force, its parent's the same way, then the parent's
 *  parent's, up to three levels up; undefined when none applies.
 *
 *  Given a claim's added number (`added`, see `Claim.added`), the rate that claim takes: the same way, among only
 *  the rate versions that apply to it — those that apply to every claim and the forward-only ones saved before it
 *  was added — the newest of each from-date. Without one, the rate in force, whatever claim it is for. */
export function rateFor(rates: Rate[] | undefined, grade: string | undefined, on: string | undefined,
  added?: number): string | undefined {
  if (on === undefined) return undefined;
  for (let level = 0; level <= 3; level++) {
    let found: Rate | undefined;
    for (const r of rates ?? []) {
      if ((r.level ?? 0) !== level || r.grade !== grade || (r.from !== null && r.from > on)) continue;
      if (added === undefined ? r.superseded : r.after != null && r.after >= added) continue;
      if (found === undefined || (found.from ?? '') < (r.from ?? '')
        || ((found.from ?? '') === (r.from ?? '') && (found.version ?? 0) < (r.version ?? 0))) found = r;
    }
    if (found !== undefined && (found.to == null || found.to >= on)) return found.pct;
  }
  return undefined;
}

/** A two-decimal number as a whole count of hundredths ("12.50" -> 1250, "-0.30" -> -30). */
export function hundredths(v: string): bigint {
  const t = v.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const cents = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -cents : cents;
}

/** A whole count of hundredths as a two-decimal number (-30 -> "-0.30"). */
export function money(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${(abs % 100n).toString().padStart(2, '0')}`;
}

/** A rate figure: an amount (two decimals) times a rate (a two-decimal percent), divided by 100, rounded
 *  half up (when `halfUp`) or half to even to two decimals — not floored (see `atLeast`); 'n/a' when there is
 *  no rate. Worked in whole numbers, so exact. */
export function due(amount: string, pct: string | undefined, halfUp: boolean): string {
  if (pct === undefined) return 'n/a';
  return money(percentOf(amount, pct, 1n, halfUp));
}

/** A holder's part of a claim: its amount (two decimals) times a share (a two-decimal percent) divided by 100, times
 *  a rate (a two-decimal percent) divided by 100, rounded half up (when `halfUp`, away from zero) or half to even to
 *  two decimals; 'n/a' when there is no rate. Worked in whole numbers, so exact. */
export function heldPart(amount: string, share: string, pct: string | undefined, halfUp: boolean): string {
  if (pct === undefined) return 'n/a';
  const signed = hundredths(amount) * hundredths(share) * hundredths(pct); // in 1/1_000_000 of a unit, before the two divisions by 100
  const product = signed < 0n ? -signed : signed;
  const rest = product % 100000000n;
  let cents = product / 100000000n;
  if (rest > 50000000n || (rest === 50000000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return money(signed < 0n ? -cents : cents);
}

/** A figure (two decimals) raised to at least a floor (two decimals; none when undefined); 'n/a' stays 'n/a'. */
export function atLeast(figure: string, floor: string | undefined): string {
  if (figure === 'n/a' || floor === undefined || hundredths(figure) >= hundredths(floor)) return figure;
  return money(hundredths(floor));
}

/** Whether an amount (two decimals) is a correction's: below zero. */
export function isCorrection(amount: string): boolean {
  return hundredths(amount) < 0n;
}

/** An amount (two decimals) times a rate (a two-decimal percent) times a whole number, divided by
 *  100, rounded half up (when `halfUp`, away from zero) or half to even, in hundredths (a negative amount rounds as its size does, then takes
 *  its sign back). */
function percentOf(amount: string, pct: string, times: bigint, halfUp: boolean): bigint {
  const signed = hundredths(amount) * hundredths(pct) * times; // in 1/1_000_000 of a unit
  const product = signed < 0n ? -signed : signed;
  const rest = product % 10000n;
  let cents = product / 10000n;
  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
  return signed < 0n ? -cents : cents;
}

/** A figure (two decimals) with a late charge added on top: for each full 30 days, the late percent
 *  (two decimals) in force on that boundary of the figure plus the charges of the boundaries before it (compounding), each rounded like a due, the charges added up;
 *  'n/a' stays 'n/a'. */
export function withCharge(figure: string, latePcts: string[], halfUp: boolean): string {
  if (figure === 'n/a') return figure;
  return money(latePcts.reduce((sum, pct) => sum + percentOf(money(sum), pct, 1n, halfUp), hundredths(figure)));
}

/** Dues added up, skipping 'n/a'. */
export function sumDues(dues: string[]): string {
  return money(dues.filter((d) => d !== 'n/a').reduce((sum, d) => sum + hundredths(d), 0n));
}

/** A sheet's total of people's figures: added up, skipping 'n/a', but leaving out the single highest
 *  and the single lowest figure when three or more people have one. */
export function trimmedSum(figures: string[]): string {
  const cents = figures.filter((d) => d !== 'n/a').map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = cents.length >= 3 ? cents.slice(1, -1) : cents;
  return money(kept.reduce((sum, c) => sum + c, 0n));
}

